"""Build a crawlable, bilingual static site from a published aggregate snapshot.
No runtime dependencies. Use --offline for a reproducible build from snapshot.json.
"""
import json, os, sys, html, urllib.request, urllib.parse, datetime
from pathlib import Path
R=Path(__file__).parent; OUT=R/'site'; C=json.loads((R/'config.json').read_text()); D=json.loads((R/'snapshot.json').read_text())
if '--offline' not in sys.argv:
    try:
        req=urllib.request.Request(C['supabaseUrl']+'/rest/v1/research_snapshots?select=payload&status=eq.published&order=snapshot_date.desc&limit=1',headers={'apikey':C['supabaseKey']})
        fetched=json.load(urllib.request.urlopen(req,timeout=15))
        if fetched: D=fetched[0]['payload']
        print('Loaded published snapshot from Supabase')
    except Exception as e: print('Using dated local snapshot; Supabase unavailable:',type(e).__name__)
assert D['total']==D['sale']+D['rent']
assert all(c['n']>=5 and c['q1']<=c['median']<=c['q3'] for c in D['cities'])
BASE=os.environ.get('SITE_URL',C['siteUrl']).rstrip('/'); esc=lambda x:html.escape(str(x),quote=True)
def money(x):return '$'+f'{x:,.0f}'
pages=[]
for lang in ['ar','en']:
    ar=lang=='ar'; pre='' if ar else '/en'
    def T(a,e):return a if ar else e
    def url(p=''):return pre+'/'+p.strip('/')+('/' if p.strip('/') else '')
    def cityname(c):return c[lang]
    def listing(c=None,kind='sale'):
        q={'listing':kind,'type':'apartment'}
        if c:q['gov']=c['ar']
        return 'https://shamaqar.net/properties?'+urllib.parse.urlencode(q)
    def btn(label,href,klass=''):return f'<a class="btn {klass}" href="{esc(href)}">{label} <span aria-hidden="true">↗</span></a>'
    def stat(label,value,note):return f'<div class="stat"><label>{label}</label><strong>{value}</strong><small>{note}</small></div>'
    def source():return f'<div class="source-note">{T("لقطة منشورة بتاريخ","Published snapshot:")} <bdi>{D["date"]}</bdi> · {T("أسعار مطلوبة، وليست أسعار صفقات.","Asking prices, not completed sale prices.")} <a href="{D["source"]}">{T("المصدر: مؤشرات شام عقار","Source: Sham Aqar indicators")}</a> · <a href="{url("methodology")}">{T("المنهجية وحدود البيانات","Methodology & limitations")}</a></div>'
    def cta():return f'<div class="cta"><div><p class="eyebrow">SHAM AQAR · شام عقار</p><h2>{T("من قراءة السوق إلى عقارك القادم.","From market insight to your next home.")}</h2><p>{T("تصفّح العقارات وتواصل مباشرة مع المعلنين على شام عقار.","Explore properties and contact advertisers directly on Sham Aqar.")}</p></div>{btn(T("تصفّح عقارات شام عقار","Explore Sham Aqar"),'https://shamaqar.net/properties')}</div>'
    def page(path,title,desc,content,nav='',schema=None):
        canonical=BASE+url(path); other=('/en/' if ar else '/')+path.strip('/')+('/' if path else '')
        org={'@type':'Organization','@id':'https://shamaqar.net/#organization','name':'Sham Aqar — شام عقار','url':'https://shamaqar.net','logo':'https://shamaqar.net/assets/sham-aqar-logo-hd.png'}
        ld={'@context':'https://schema.org','@graph':[org,{'@type':'WebSite','@id':BASE+'/#website','name':T('شام عقار | الأبحاث والأدوات','Sham Aqar | Research & Tools'),'url':BASE,'publisher':{'@id':org['@id']},'inLanguage':['ar','en']},{'@type':'WebPage','@id':canonical+'#page','url':canonical,'name':title,'description':desc,'inLanguage':lang,'isPartOf':{'@id':BASE+'/#website'}}]}
        if schema:ld['@graph'].append(schema)
        links=[('',T('الرئيسية','Overview')),('reports',T('تقارير السوق','Market reports')),('tools/yield',T('الأدوات','Tools')),('methodology',T('المنهجية','Methodology'))]
        navhtml=''.join(f'<a class="{"active" if k==nav else ""}" href="{url(k)}">{v}</a>' for k,v in links)
        crumbs='' if not path else f'<div class="wrap crumbs"><a href="{url()}">{T("الرئيسية","Home")}</a><span>/</span><span>{title}</span></div>'
        output=f'''<!doctype html><html lang="{lang}" dir="{'rtl' if ar else 'ltr'}"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>{esc(title)} | {T('شام عقار للأبحاث','Sham Aqar Research')}</title><meta name="description" content="{esc(desc)}"><meta name="theme-color" content="#172c32"><link rel="canonical" href="{canonical}"><link rel="alternate" hreflang="ar" href="{BASE+'/'+path.strip('/')+('/' if path else '')}"><link rel="alternate" hreflang="en" href="{BASE+'/en/'+path.strip('/')+('/' if path else '')}"><link rel="alternate" hreflang="x-default" href="{BASE+'/'+path.strip('/')+('/' if path else '')}"><meta property="og:title" content="{esc(title)}"><meta property="og:description" content="{esc(desc)}"><meta property="og:type" content="website"><meta property="og:url" content="{canonical}"><meta property="og:image" content="{BASE}/assets/hero.webp"><meta property="og:locale" content="{'ar_SY' if ar else 'en_US'}"><meta name="twitter:card" content="summary_large_image"><link rel="icon" href="/assets/logo.png"><link rel="stylesheet" href="/assets/style.css"><script type="application/ld+json">{json.dumps(ld,ensure_ascii=False).replace('</','<\\/')}</script><script defer src="/assets/math.js"></script><script defer src="/assets/app.js"></script></head><body><a class="skip" href="#main">{T('انتقل إلى المحتوى','Skip to content')}</a><div class="topline"><div class="wrap"><span>{T('الأبحاث والأدوات العقارية من شام عقار','PROPERTY RESEARCH & TOOLS BY SHAM AQAR')}</span><span>{T('بيانات واضحة. قرارات مدروسة.','CLEARER DATA. BETTER-INFORMED DECISIONS.')}</span></div></div><header><div class="wrap nav"><a class="brand" href="{url()}"><img src="/assets/logo.png" alt="" width="48" height="48"><span><strong>{T('شام عقار','Sham Aqar')}</strong><small>{T('الأبحاث والأدوات','RESEARCH & TOOLS')}</small></span></a><nav aria-label="{T('القائمة الرئيسية','Main navigation')}">{navhtml}</nav><div class="nav-actions"><a class="lang" href="{other}" lang="{'en' if ar else 'ar'}">{'EN' if ar else 'العربية'}</a>{btn(T('إلى شام عقار','Visit Sham Aqar'),'https://shamaqar.net','light')}</div></div></header>{crumbs}<main id="main" class="wrap">{content}</main><footer class="footer"><div class="wrap"><div class="footer-grid"><div><a class="brand" href="https://shamaqar.net"><span><strong>{T('شام عقار','Sham Aqar')}</strong><small>RESEARCH & TOOLS</small></span></a><p>{T('معرفة أوضح بالسوق العقاري السوري. تقارير وأدوات من شام عقار تساعدك على فهم الأرقام قبل اتخاذ القرار.','A clearer view of Syrian real estate. Research and practical tools from Sham Aqar to help you understand the numbers behind a decision.')}</p></div><div><h3>{T('استكشف','Explore')}</h3><div class="footer-links"><a href="{url('reports')}">{T('تقارير المحافظات','Governorate reports')}</a><a href="{url('compare')}">{T('مقارنة المحافظات','Compare governorates')}</a><a href="{url('tools/yield')}">{T('حاسبة العائد الإيجاري','Rental yield calculator')}</a><a href="{url('about')}">{T('عن هذا المركز','About this hub')}</a></div></div><div><h3>{T('منصة شام عقار','Sham Aqar platform')}</h3><div class="footer-links"><a href="https://shamaqar.net/properties">{T('ابحث عن عقار','Find a property')}</a><a href="https://shamaqar.net/listings/new">{T('أضف عقارك','List your property')}</a><a class="app-link" href="https://play.google.com/store/apps/details?id=net.shamaqar.app">Google Play ↗</a><a href="https://shamaqar.net/contact">{T('تواصل معنا','Contact us')}</a></div></div></div><div class="footnote"><span>© 2026 Sham Aqar · {T('شام عقار للأبحاث والأدوات','Research & Tools')}</span><span><a href="{url('methodology')}">{T('المنهجية','Methodology')}</a> · <a href="{url('privacy')}">{T('الخصوصية','Privacy')}</a> · {T('أرقام استرشادية وليست تقييماً عقارياً','Informational figures, not a property valuation')}</span></div></div></footer></body></html>'''
        dest=OUT/url(path).strip('/')/'index.html';dest.parent.mkdir(parents=True,exist_ok=True);dest.write_text(output)
        pages.append(canonical)
    def cards():
        out='<div class="cards">'
        for c in D['cities']:
            out+=f'<article class="card"><div class="card-top"><span>{T("تقرير المحافظة","GOVERNORATE REPORT")}</span><span class="tag">{T("شقق للبيع","Apartments for sale")}</span></div><h3>{cityname(c)}</h3><div class="card-number">{money(c["median"])} <small>/ m²</small></div><p>{T("وسيط سعر المتر المطلوب في العيّنة المسعّرة","Median asking price per m² in the priced sample")}</p><div class="meter" aria-hidden="true"><span style="width:{c["median"]/max(x["median"] for x in D["cities"])*100}%"></span></div><p>{T("العينة:","Sample:")} {c["n"]} {T("شقة بسعر ومساحة صالحين","apartments with valid price and area")}</p><div class="card-bottom"><span>{D["date"]}</span><a href="{url("reports/"+c["slug"])}">{T("قراءة التقرير ←","Read report →")}</a></div></article>'
        return out+'</div>'
    def intro(eye,title,desc):return f'<div class="page-hero"><p class="eyebrow">{eye}</p><h1>{title}</h1><p class="lede">{desc}</p></div>'
    home=f'''<section class="hero"><div><p class="eyebrow">{T('مرصد شام عقار · سوريا','SHAM AQAR OBSERVATORY · SYRIA')}</p><h1>{T('اقرأ السوق.<br><em>واختر بثقة أكبر.</em>','Understand the market.<br><em>Find your perspective.</em>')}</h1><p class="lede">{T('تقارير عقارية مبنية على الإعلانات المنشورة في شام عقار، وأدوات تساعدك على المقارنة وحساب العائد. لأن القرار الجيد يبدأ بأرقام مفهومة.','Property research grounded in published Sham Aqar listings, with practical tools to compare asking prices and explore rental returns. A considered decision starts with understandable numbers.')}</p><div class="actions">{btn(T('استكشف تقارير السوق','Explore market reports'),url('reports'))}{btn(T('احسب عائد عقارك','Calculate rental yield'),url('tools/yield'),'light')}</div><p class="hero-note"><span class="status">{T('لقطة البيانات','Data snapshot')} {D['date']}</span> · {T('المصدر: شام عقار','Source: Sham Aqar')}</p></div><div class="hero-visual"><img src="/assets/hero.webp" alt="{T('تصور معماري لفيلا من هوية شام عقار','Villa architectural illustration from Sham Aqar') }" width="800" height="363" fetchpriority="high"><span class="image-label">{T('تصور معماري · شام عقار','ARCHITECTURAL ILLUSTRATION · SHAM AQAR')}</span><div class="float-card"><strong>{D['total']}</strong><span>{T('إعلاناً نشطاً في المنصة<br>ضمن لقطة البيانات','active platform listings<br>in this snapshot')}</span><div class="mini-bars" aria-hidden="true"><i style="height:40%"></i><i style="height:70%"></i><i style="height:55%"></i><i style="height:90%"></i></div></div></div></section><div class="stats">{stat(T('إعلانات للبيع','For-sale listings'),D['sale'],T('كل أنواع العقارات','All property types'))}{stat(T('إعلانات للإيجار','Rental listings'),D['rent'],T('كل مدد الإيجار','All rental periods'))}{stat(T('وسيط سعر الشقة للبيع','Median apartment asking price'),money(D['apartmentMedian']),T(str(D['apartmentSample'])+' شقة مسعّرة في العينة',str(D['apartmentSample'])+' priced apartments in sample'))}{stat(T('محافظات ببيانات سعر المتر','Governorates with price-per-m² data'),str(len(D['cities'])).zfill(2),T('5 إعلانات صالحة على الأقل لكل فئة','At least 5 valid listings per group'))}</div><section class="section"><div class="section-head"><div><p class="eyebrow">{T('ابدأ بالمكان','START WITH A PLACE')}</p><h2>{T('نظرة أقرب إلى كل سوق','A closer look at each market')}</h2><p>{T('وسيط سعر المتر للشقق المعروضة للبيع، مع حجم العينة وحدود المقارنة.','Median apartment asking price per m², with sample sizes and context.')}</p></div><a class="text-link" href="{url('compare')}">{T('قارن المحافظات ←','Compare markets →')}</a></div>{cards()}</section><section class="split"><div class="dark"><p class="eyebrow">{T('أدوات من شام عقار','TOOLS BY SHAM AQAR')}</p><h2>{T('ضع الأرقام في سياقها.','Make the numbers useful.')}</h2><p>{T('اختبر افتراضاتك قبل البحث. الحسابات تتم في متصفحك، ولا نرسل القيم التي تدخلها.','Explore your own assumptions before you search. Calculations stay in your browser; your inputs are not sent to us.')}</p><div class="tools-mini">'''
    for path,symbol,at,et,ad,ed in [('yield','%','العائد الإيجاري','Rental yield','إجمالي وصافي العائد وفترة الاسترداد','Gross yield, net yield and payback'),('sqm','m²','سعر المتر المربع','Price per square metre','مقارنة عقارات تختلف في المساحة','Compare differently sized properties'),('rent-buy','⇄','الإيجار أم الشراء؟','Rent or buy?','مقارنة التدفقات النقدية بافتراضات واضحة','Compare cash outflows with clear assumptions')]:
        home+=f'<a class="tool-row" href="{url("tools/"+path)}"><span class="symbol">{symbol}</span><span><b>{T(at,et)}</b><small>{T(ad,ed)}</small></span><span class="arrow">↗</span></a>'
    home+=f'</div></div><div class="chart-panel"><p class="eyebrow">{T("توزّع العرض","SUPPLY AT A GLANCE")}</p><h2>{T("أين تتركّز الإعلانات؟","Where are listings concentrated?")}</h2><p class="note">{T("عدد الإعلانات النشطة بكل أنواع العقارات، وليس عيّنة الأسعار.","Active listings across all property types, not the pricing sample.")}</p>'
    for c in D['cities']:home+=f'<div class="bar-row"><span>{cityname(c)}</span><div class="bar-track"><div class="bar-fill" style="width:{c["active"]/278*100}%"></div></div><b>{c["active"]}</b></div>'
    home+=f'<p class="note">{T(f"تضم المحافظات المعروضة {sum(c['active'] for c in D['cities'])} إعلاناً من أصل {D['total']}. لا تعني كثافة العرض في المنصة حجم السوق العقاري كاملاً.",f"The featured governorates account for {sum(c['active'] for c in D['cities'])} of {D['total']} listings. Platform supply does not measure the size of the entire housing market.")}</p><a class="text-link" href="{D["source"]}">{T("اطّلع على المؤشرات الأصلية ←","View the original indicators →")}</a></div></section><section class="section">{source()}<div class="method-strip">'
    for i,a,e,aa,ee in [('01','مصدر معلن','Traceable sources','لكل رقم تاريخ ومصدر يمكنك الرجوع إليه.','Every figure has a date and a source you can inspect.'),('02','عينات واضحة','Visible sample sizes','نوضح عدد الإعلانات ونمتنع عن استنتاج أسعار من عينات صغيرة.','We show listing counts and withhold pricing conclusions for sparse samples.'),('03','قرارك أولاً','Your decision, informed','الأرقام نقطة بداية؛ حالة العقار وموقعه وتفاصيله تصنع الفارق.','Numbers are a starting point; condition, location and property details matter.')]:home+=f'<div><span class="num">{i}</span><b>{T(a,e)}</b><p>{T(aa,ee)}</p></div>'
    home+='</div></section>'+cta()
    page('',T('أبحاث السوق العقاري السوري وأدوات المقارنة','Syrian property research & comparison tools'),T('تقارير أسعار العقارات في سوريا وأدوات العائد الإيجاري وسعر المتر، من شام عقار، مع مصادر وحجم العينة.','Syrian property asking-price reports, rental yield and price-per-m² calculators from Sham Aqar, with sources and sample sizes.'),home)
    reports=intro(T('الأبحاث العقارية','PROPERTY RESEARCH'),T('أرقام واضحة. وسياق ضروري.','Clear figures. Essential context.'),T('تقرأ هذه التقارير لقطة المؤشرات المنشورة في شام عقار. نركّز على المحافظات التي تتوفر فيها عينة كافية، ونوضح أين لا تكفي البيانات.','These reports interpret a dated snapshot of Sham Aqar’s published indicators. We focus on governorates with sufficient observations and explain where coverage is limited.'))+source()+f'<section class="section">{cards()}</section>'
    reports+=f'<div class="empty-state"><h3>{T("وماذا عن حلب وحمص؟","What about Aleppo and Homs?")}</h3><p>{T("تحتوي هذه اللقطة على إعلان واحد في حلب و3 إعلانات في حمص، بكل أنواع العقارات. هذه الأعداد لا تكفي لنشر متوسطات أو وسائط أسعار يمكن الاعتماد عليها. يمكنك تصفح العرض الحالي مباشرة على شام عقار.","This snapshot contains one listing in Aleppo and three in Homs across all property types. Those counts are insufficient for credible pricing statistics. Explore current supply directly on Sham Aqar.")}</p><div class="inline-links"><a class="text-link" href="{listing({"ar":"حلب"})}">{T("عقارات حلب","Aleppo apartments")} ↗</a><a class="text-link" href="{listing({"ar":"حمص"})}">{T("عقارات حمص","Homs apartments")} ↗</a></div></div><section class="section">{cta()}</section>'
    page('reports',T('تقارير سوق العقارات حسب المحافظة','Property market reports by governorate'),T('تقارير دمشق وريف دمشق واللاذقية، مع حدود التغطية في حلب وحمص.','Damascus, Rural Damascus and Latakia reports, plus coverage limitations for Aleppo and Homs.'),reports,'reports')
    interpretations={
    'damascus':('تعكس هذه العينة تفاوتاً مهماً داخل دمشق: يقع النصف الأوسط من أسعار المتر بين 1,462 و2,080 دولاراً. رقم المحافظة لا يحدد سعر حي أو شارع بعينه؛ التشطيب والطابق وحالة البناء والمساحة قد تغيّر المقارنة.','The sample shows substantial variation within Damascus: the middle half of per-m² asking prices ranges from $1,462 to $2,080. A governorate-wide figure does not price a particular street. Finish, floor, building condition and area can materially affect comparability.'),
    'rural-damascus':('ريف دمشق نطاق جغرافي واسع يضم أسواقاً مختلفة. يقع النصف الأوسط من أسعار المتر بين 189 و438 دولاراً في هذه العينة. لا يصح نقل هذا الوسيط إلى كل منطقة؛ قارن عقارات متقاربة في الموقع والحالة قبل الحكم على السعر.','Rural Damascus covers a broad area containing distinct local markets. The middle half of per-m² asking prices ranges from $189 to $438 in this sample. Apply comparisons to similar locations and property conditions rather than treating the governorate median as a valuation.'),
    'latakia':('تستند قراءة سعر المتر في اللاذقية إلى 6 شقق فقط، وهي عينة صغيرة وقريبة من حد النشر. النطاق من 207 إلى 423 دولاراً يصف النصف الأوسط من هذه العينة وحدها. إضافة عدد قليل من الإعلانات قد تغيّر القراءة بشكل ملحوظ.','Latakia’s price-per-m² figure rests on only six apartments, a small sample close to the publication threshold. The $207–$423 interquartile range describes this sample alone. A few additional listings could materially change the result.')}
    for c in D['cities']:
        title=T('قراءة سوق الشقق في '+c['ar'],c['en']+' apartment market briefing')
        content=intro(T('تقرير محافظة · أكتوبر 2026','GOVERNORATE BRIEFING · OCTOBER 2026'),title,T('أسعار مطلوبة في إعلانات شام عقار. قراءة مؤرخة للعرض المنشور، وليست تقييماً لكل عقارات المحافظة.','Asking prices from Sham Aqar listings. A dated view of published supply, not a valuation of every property in the governorate.'))+source()
        content+=f'<section class="section report-grid"><article class="article"><div class="band"><span class="tag">{T("شقق للبيع","APARTMENTS FOR SALE")}</span><button class="print-btn" id="print">{T("طباعة التقرير","Print report")}</button></div><h2>{T("ماذا تقول العينة؟","What does the sample say?")}</h2><p>{T("وسيط سعر المتر المطلوب هو","The median asking price per m² is")} <strong>{money(c["median"])}</strong>، {T("استناداً إلى","based on")} <strong>{c["n"]}</strong> {T("شقة بسعر ومساحة صالحين للحساب.","apartments with valid price and area.")}</p><div class="metric-range"><div><small>{T("الربع الأدنى","Lower quartile")}</small><strong>{money(c["q1"])}</strong></div><div><small>{T("الوسيط / م²","Median / m²")}</small><strong>{money(c["median"])}</strong></div><div><small>{T("الربع الأعلى","Upper quartile")}</small><strong>{money(c["q3"])}</strong></div></div><p>{T(*interpretations[c["slug"]])}</p><h2>{T("افصل عينة الأسعار عن عدد الإعلانات","Separate the pricing sample from listing counts")}</h2><p>{T("تضم لقطة المحافظة","The governorate snapshot contains")} {c["active"]} {T("إعلاناً نشطاً بكل أنواع العقارات:","active listings across all property types:")} {c["sale"]} {T("للبيع و","for sale and")} {c["rent"]} {T("للإيجار. هذا العدد أكبر من عينة سعر المتر، لأن حساب السعر يتطلب نوعاً محدداً وسعراً ومساحة صالحين.","for rent. This is larger than the per-m² sample because pricing requires a specific property type and valid price and area values.")}</p><h2>{T("كيف تستخدم الرقم في بحثك؟","How to use the figure in your search")}</h2><ul><li>{T("ابدأ بعقارات من المنطقة نفسها وبمساحات وحالة بناء متقاربة.","Start with properties in the same area, with comparable sizes and building condition.")}</li><li>{T("احسب السعر لكل متر، ثم راجع السعر الإجمالي والتكاليف الإضافية.","Calculate price per m², then consider the total price and additional costs.")}</li><li>{T("راجع تاريخ الإعلان وتأكد من المعلن أن العرض والسعر ما زالا قائمين.","Check the listing date and confirm availability and price with the advertiser.")}</li></ul><h2>{T("ما الذي لا تثبته هذه البيانات؟","What these figures do not establish")}</h2><p>{T("لا تعرض هذه اللقطة أسعار صفقات منجزة أو مستوى الطلب الفعلي، ولا تقيس تغير الأسعار مقارنة بالشهر الماضي. اختلاف العينات قد يفسر الفروق بين المحافظات. البيانات تخص الإعلانات النشطة في شام عقار بتاريخ اللقطة.","This snapshot does not show completed sale prices, actual demand, or month-on-month price changes. Sample composition can explain differences between governorates. It covers active Sham Aqar listings on the snapshot date.")}</p><a class="text-link" href="{url("methodology")}">{T("اقرأ المنهجية الكاملة","Read the full methodology")} →</a></article><aside class="sidebar"><div class="dark"><p class="eyebrow">{T("تابع بحثك مع شام عقار","CONTINUE WITH SHAM AQAR")}</p><h2>{T("شاهد العقارات في","Explore properties in")} {cityname(c)}</h2><p>{T("راجع الإعلانات الحالية وتفاصيل كل عقار قبل اتخاذ قرارك.","Review current listings and each property’s details before deciding.")}</p>{btn(T("شقق للبيع","Apartments for sale"),listing(c),'gold')}<div class="inline-links"><a href="{listing(c,'rent')}">{T("شقق للإيجار ←","Apartments for rent →")}</a></div></div><div class="card"><h3>{T("مقارنة أدق","Compare more carefully")}</h3><p>{T("استخدم مساحة العقار وسعره المطلوب لحساب سعر المتر.","Use a property’s actual area and asking price to calculate its price per m².")}</p><a class="text-link" href="{url("tools/sqm")}">{T("افتح حاسبة سعر المتر","Open price-per-m² calculator")} →</a></div><div class="card"><h3>{T("بيانات قابلة للتنزيل","Download the figures")}</h3><p>{T("أرقام هذه اللقطة مع التاريخ والمصدر وحجم العينة.","Snapshot figures with date, source and sample sizes.")}</p><a class="text-link" href="/data/market-snapshot.csv" download>CSV ↓</a></div></aside></section>'+cta()
        page('reports/'+c['slug'],title,T('أسعار الشقق المطلوبة في '+c['ar']+'، مع وسيط سعر المتر وحجم العينة والمنهجية.',c['en']+' apartment asking prices, price-per-m² median, sample size and methodology.'),content,'reports',{'@type':'Article','headline':title,'datePublished':D['date'],'dateModified':D['date'],'author':{'@id':'https://shamaqar.net/#organization'},'publisher':{'@id':'https://shamaqar.net/#organization'},'citation':D['source'],'inLanguage':lang})
    # Tools: explanatory content remains visible and crawlable without JavaScript.
    toolmeta={'yield':('حاسبة العائد الإيجاري','Rental yield calculator','قدّر العائد الإجمالي والصافي وفترة استرداد تكلفة العقار، باستخدام افتراضاتك أنت.','Estimate gross yield, net yield and simple payback using your own assumptions.'),'sqm':('حاسبة سعر المتر المربع','Price per square metre','حوّل السعر والمساحة إلى رقم قابل للمقارنة. استخدم العملة نفسها عند مقارنة أكثر من عقار.','Turn asking price and area into a comparable figure. Use the same currency across properties.'),'rent-buy':('مقارنة الإيجار والشراء','Rent-versus-buy cash comparison','قارن المدفوعات النقدية في سيناريو مبسّط، وافهم ما يشمله الحساب وما يستبعده.','Compare cash outflows in a simplified scenario and understand what the calculation includes and excludes.')}
    def field(id,label,value,min=0,max=None,step='any',hint=''):
        mx=f' max="{max}"' if max is not None else ''
        return f'<div class="field"><label for="{id}">{label}</label><input type="number" inputmode="decimal" id="{id}" name="{id}" value="{value}" min="{min}"{mx} step="{step}" required><small>{hint}</small></div>'
    def resultrow(label,id):return f'<div class="result-row"><span>{label}</span><b id="{id}">—</b></div>'
    for kind,m in toolmeta.items():
        title=T(m[0],m[1]);desc=T(m[2],m[3]);tabs='<div class="tabs">'+''.join(f'<a class="{"active" if k==kind else ""}" href="{url("tools/"+k)}">{T(mm[0],mm[1])}</a>' for k,mm in toolmeta.items())+'</div>'
        fields=field('price',T('سعر شراء العقار ($)','Property purchase price ($)'),100000,1)
        if kind=='sqm':fields+=field('area',T('المساحة (م²)','Area (m²)'),120,.01);primary=T('السعر لكل متر مربع','Price per square metre');results=resultrow(T('المساحة المدخلة','Entered area'),'area-result')+resultrow(T('السعر الإجمالي','Total price'),'total-result');formula=T('سعر المتر = السعر الإجمالي ÷ المساحة بالمتر المربع.','Price per m² = total asking price ÷ area in square metres.');explain=T('المقارنة مفيدة عندما تكون المساحات مقاسة بالطريقة نفسها. المساحة الداخلية ليست دائماً المساحة الإجمالية، ولا يقيس هذا الرقم حالة العقار أو جودة الموقع.','The comparison is useful only when areas are measured consistently. Internal usable area is not necessarily gross area. This metric does not account for property condition or location quality.')
        else:
            fields+=field('rent',T('الإيجار الشهري المتوقع ($)','Expected monthly rent ($)'),500)+field('costs',T('تكاليف شراء وتجهيز إضافية ($)','Additional purchase/setup costs ($)'),5000)
            if kind=='yield':
                fields+='<div class="field-grid">'+field('vacancy',T('أشهر الشغور سنوياً','Vacant months per year'),1,0,12,.5)+field('annual',T('مصاريف سنوية ($)','Annual expenses ($)'),1200)+'</div>';primary=T('صافي العائد السنوي التقديري','Estimated annual net yield');results=resultrow(T('العائد الإجمالي','Gross yield'),'gross')+resultrow(T('صافي الدخل السنوي','Annual net income'),'net')+resultrow(T('فترة الاسترداد البسيطة','Simple payback'),'payback');formula=T('الإجمالي = الإيجار الشهري × 12 ÷ سعر الشراء. الصافي = [الإيجار × (12 − أشهر الشغور) − المصاريف السنوية] ÷ (سعر الشراء + التكاليف الإضافية).','Gross yield = monthly rent × 12 ÷ purchase price. Net yield = [rent × (12 − vacant months) − annual expenses] ÷ (purchase price + additional costs).');explain=T('فترة الاسترداد = إجمالي تكلفة الشراء ÷ صافي الدخل السنوي. لا يشمل الحساب ارتفاع قيمة العقار أو التمويل أو الضرائب إلا إذا أضفت التكاليف المناسبة إلى مدخلاتك. القيم الافتراضية مثال حسابي وليست أسعار سوق.','Simple payback = total acquisition cost ÷ annual net income. Appreciation, financing and taxes are not included unless you include applicable expenses in your inputs. Default values are an arithmetic example, not market estimates.')
            else:
                fields+='<div class="field-grid">'+field('maintenance',T('صيانة سنوية (% من سعر العقار)','Annual upkeep (% of purchase price)'),1,0,100,.1)+field('years',T('مدة المقارنة بالسنوات','Comparison horizon (years)'),5,1,50,1)+'</div>';primary=T('إجمالي الإيجار خلال المدة','Total rent over the period');results=resultrow(T('مدفوعات الشراء والصيانة','Purchase + upkeep cash outlay'),'buy')+resultrow(T('الصيانة السنوية','Annual upkeep'),'maintenance-result')+resultrow(T('السعر ÷ الإيجار السنوي','Price ÷ annual rent'),'ratio');formula=T('مدفوعات الإيجار = الإيجار الشهري × 12 × السنوات. مدفوعات الشراء = السعر + التكاليف الإضافية + الصيانة السنوية × السنوات.','Rent paid = monthly rent × 12 × years. Buying cash outlay = price + additional costs + annual upkeep × years.');explain=T('هذه مقارنة مدفوعات وليست مقارنة ثروة أو توصية بالإيجار أو الشراء. يحتفظ المشتري بأصل عقاري في نهاية الفترة. لا نحتسب إعادة البيع أو تغير الأسعار والإيجارات أو التمويل أو تكلفة الفرصة البديلة أو الضرائب. القيم الافتراضية أمثلة فقط.','This compares cash outflows, not net wealth, and does not recommend renting or buying. The buyer still owns a property at the end. Resale value, changing prices/rents, financing, opportunity cost and taxes are excluded. Default values are illustrative only.')
        content=intro(T('أدوات شام عقار','SHAM AQAR TOOLS'),title,desc)+tabs+f'<div class="calculator"><form class="calc-fields" data-calculator="{kind}"><h2>{T("أدخل افتراضاتك","Enter your assumptions")}</h2><p class="note">{T("كل المبالغ بالدولار الأمريكي. القيم الأولية مثال للتجربة.","All amounts are in US dollars. Initial values are an example.")}</p>{fields}</form><section class="calc-results" aria-live="polite" aria-atomic="true"><label>{primary}</label><div class="big-result" id="primary">—</div><p class="error" id="calc-error"></p>{results}<p class="note">{T("الحساب يتم على جهازك؛ لا يتم حفظ المدخلات أو إرسالها.","Calculated on your device; inputs are neither stored nor transmitted.")}</p><noscript>{T("فعّل JavaScript لتشغيل الحاسبة. المعادلات موضّحة أدناه.","Enable JavaScript to use the calculator. Formulas are explained below.")}</noscript></section></div><section class="section"><article class="article"><h2>{T("كيف نحسب النتيجة؟","How the calculation works")}</h2><p>{formula}</p><h2>{T("افهم حدود المقارنة","Understand the limitations")}</h2><p>{explain}</p><div class="inline-links"><a class="text-link" href="https://shamaqar.net/properties?listing=sale">{T("تصفّح عقارات للبيع على شام عقار","Browse properties for sale on Sham Aqar")} ↗</a><a class="text-link" href="https://shamaqar.net/properties?listing=rent">{T("راجع الإيجارات المعروضة","Explore advertised rentals")} ↗</a></div></article></section>'+cta()
        page('tools/'+kind,title,desc,content,'tools/yield')
